import os
import ast

write_keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def contains_write_indicator(func_source):
    for kw in write_keywords:
        if kw in func_source:
            return kw
    return None

def analyze_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    try:
        tree = ast.parse(content)
    except SyntaxError:
        return

    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Check if legacy_auth is called inside this function
            calls_legacy = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                    calls_legacy = True
                    break

            if calls_legacy:
                func_lines = content.splitlines()[node.lineno-1:node.end_lineno]
                func_source = "\n".join(func_lines)
                kw = contains_write_indicator(func_source)
                print(f"File: {filepath}, Function: {node.name}")
                print(f"  Lines: {node.lineno}-{node.end_lineno}")
                print(f"  Write keyword found: {kw}")
                print(f"  Source fragment:\n{func_source}\n")

for root, dirs, files in os.walk('app'):
    for file in files:
        if file.endswith('.py') and filepath := os.path.join(root, file):
            if filepath == 'app/auth.py':
                continue
            analyze_file(filepath)

